export const quizWording={
  'pengantar.definisi':['Psikologi pendidikan (educational psychology)','Bidang ini memakai penelitian psikologi untuk memahami cara siswa belajar dan cara guru mengajar.','Bidang ini mengkaji proses belajar dan mengajar.','Bidang ini hanya bertugas mendiagnosis gangguan siswa.','Bidang ini hanya membahas nilai ujian siswa.','Guru cukup memilih cara mengajar berdasarkan perasaan.'],
  'pengantar.peran':['Peran psikologi pendidikan','Bidang ini membantu guru memahami kebutuhan siswa, memilih cara mengajar, dan menilai hasilnya.','Guru perlu memahami kebutuhan siswa sebelum memilih cara mengajar.','Nilai yang sama berarti penyebab kesulitan siswa juga sama.','Satu cara mengajar cocok untuk semua siswa.','Semua siswa perlu mendapat hukuman yang sama.'],
  'pengantar.evidence':['Keputusan berbasis bukti (evidence-based decision making)','Guru memakai teori, data kelas, dan hasil penilaian untuk memilih cara mengajar. Pengalaman guru juga perlu diperiksa.','Guru perlu melihat bukti hasil belajar untuk menilai keberhasilan.','Cara mengajar yang populer memiliki bukti paling kuat.','Guru yang puas menunjukkan bahwa semua siswa sudah paham.','Berhasil sekali berarti cara itu cocok untuk semua keadaan.'],
  'pengantar.belajar':['Belajar (learning)','Pengalaman dapat mengubah kemampuan atau perilaku (behavior) dan perubahan itu bertahan cukup lama. Perubahan sesaat karena lelah berbeda.','Kemampuan berubah karena siswa berlatih.','Setiap perubahan perilaku (behavior) adalah hasil belajar.','Lelah sesaat berarti siswa mendapat kemampuan baru.','Pertumbuhan tubuh adalah hasil latihan.'],
  'pengantar.tujuan':['Tujuan pembelajaran (learning objectives)','Guru menetapkan kemampuan yang perlu dicapai siswa. Kegiatan dan penilaian harus sesuai dengan kemampuan itu.','Tes tersebut belum menilai kemampuan menganalisis kasus.','Hafal nama tokoh berarti sudah mampu menganalisis kasus.','Bentuk penilaian boleh dipilih tanpa melihat tujuan belajar.','Kegiatan yang menarik sudah memenuhi semua tujuan belajar.'],
  'pengantar.formatif':['Penilaian formatif (formative assessment)','Guru memakai informasi saat proses belajar masih berlangsung untuk memperbaiki pengajaran dan membantu siswa.','Guru memakai hasil kuis untuk menyesuaikan cara mengajar.','Setiap kuis saat belajar harus menentukan nilai akhir.','Guru cukup memberi nilai tanpa membahas kesalahan.','Hasil kuis tidak boleh mengubah rencana mengajar.'],
  'pengantar.sumatif':['Penilaian sumatif (summative assessment)','Guru menilai hasil yang dicapai siswa pada akhir suatu periode belajar, misalnya akhir semester.','Penilaian itu melihat hasil belajar pada akhir periode.','Penilaian akhir harus dilakukan setiap hari.','Penilaian akhir hanya mengukur perasaan siswa.','Penilaian akhir tidak perlu mengikuti tujuan belajar.'],
  'pengantar.transfer':['Transfer belajar (transfer of learning)','Siswa memakai pengetahuan yang sudah dipelajari pada situasi lain. Hafal materi belum tentu berarti bisa melakukannya.','Siswa menggunakan konsep pada situasi baru.','Transfer hanya terjadi saat siswa mengulang kalimat buku.','Semua pengetahuan langsung bisa dipakai di semua situasi.','Transfer berarti melupakan materi yang sudah dipelajari.'],
  'behavioristik.classical':['Pengondisian klasik (classical conditioning)','Pemicu yang awalnya tidak menimbulkan reaksi tertentu mulai memicu reaksi itu setelah dikaitkan dengan pemicu lain.','Lembar ujian menjadi pemicu yang dipelajari (conditioned stimulus).','Lembar ujian menjadi penguat (reinforcer) karena siswa merasa cemas.','Reaksi itu hanya muncul karena siswa mendapat hadiah setelah bertindak.','Pemicu yang awalnya netral tidak dapat dikaitkan dengan pengalaman baru.'],
  'behavioristik.ucs':['Stimulus dan respons tak terkondisi (unconditioned stimulus and response)','Pemicu menimbulkan reaksi alami tanpa proses belajar lebih dahulu. Pemicu itu disebut UCS (unconditioned stimulus) dan reaksinya disebut UCR (unconditioned response).','Suara keras adalah UCS; reaksi terkejut adalah UCR.','Siswa perlu belajar dulu bahwa suara keras dapat mengejutkan.','Semua reaksi spontan merupakan respons hasil belajar (conditioned response).','UCR adalah hadiah yang diberikan setelah suatu perilaku.'],
  'behavioristik.cs':['Stimulus dan respons terkondisi (conditioned stimulus and response)','Pemicu mendapat makna melalui pengalaman. Pemicu itu disebut CS (conditioned stimulus); reaksi yang dipelajari disebut CR (conditioned response).','Nada adalah CS; ketegangan terhadap nada itu adalah CR.','Nada tetap netral meskipun sudah memicu reaksi yang dipelajari.','Ketegangan terhadap nada itu adalah reaksi alami tanpa proses belajar.','Nada adalah hukuman negatif (negative punishment) setelah siswa bertindak.'],
  'behavioristik.extinction':['Pemadaman respons (extinction)','Reaksi hasil belajar melemah ketika pemicu tidak lagi dipasangkan seperti sebelumnya, atau perilaku tidak lagi mendapat penguatan.','Reaksi melemah karena hubungan yang dipelajari tidak lagi diperkuat.','Pemadaman menghapus seluruh hasil belajar secara permanen.','Reaksi melemah karena siswa mendapat hadiah tambahan.','Berhenti memasangkan pemicu justru membuat reaksi makin kuat.'],
  'behavioristik.generalization':['Generalisasi dan diskriminasi (generalization and discrimination)','Reaksi dapat muncul pada pemicu yang mirip. Siswa juga dapat belajar membedakan pemicu mana yang benar-benar berkaitan dengan pengalaman itu.','Awalnya siswa bereaksi pada pemicu mirip, lalu belajar membedakannya.','Generalisasi berarti siswa sudah membedakan dua pemicu.','Diskriminasi berarti siswa takut pada semua pemicu yang mirip.','Kedua proses itu menghilangkan semua reaksi siswa.'],
  'behavioristik.positive-reinforcement':['Penguatan positif (positive reinforcement)','Sesuatu ditambahkan setelah suatu perilaku, lalu perilaku itu makin sering muncul. Positif berarti ada penambahan.','Pujian menjadi penguat karena perilaku siswa makin sering muncul.','Pujian disebut penguat meskipun perilaku siswa tidak berubah.','Positif berarti akibatnya baik secara moral.','Pujian yang membuat perilaku makin sering muncul adalah hukuman.'],
  'behavioristik.negative-reinforcement':['Penguatan negatif (negative reinforcement)','Sesuatu yang tidak menyenangkan dihentikan setelah suatu perilaku, lalu perilaku itu makin sering muncul.','Alarm yang berhenti membuat siswa makin sering mengumpulkan tepat waktu.','Negatif berarti perilaku siswa makin jarang muncul.','Penguatan negatif berarti mengambil hadiah yang disukai siswa.','Alarm yang berhenti merupakan hukuman positif (positive punishment).'],
  'behavioristik.punishment':['Hukuman positif dan negatif (positive and negative punishment)','Hukuman membuat suatu perilaku makin jarang muncul. Positif berarti menambahkan sesuatu; negatif berarti mengambil sesuatu.','Hak diambil dan perilaku berkurang: ini hukuman negatif (negative punishment).','Mengambil sesuatu berarti melakukan penguatan negatif (negative reinforcement).','Akibat yang menyenangkan membuat perilaku makin jarang muncul.','Positif dan negatif berarti baik dan buruk secara moral.'],
  'behavioristik.shaping':['Pembentukan perilaku bertahap (shaping)','Guru memperkuat langkah kecil yang makin mendekati perilaku yang dituju, sebelum siswa mampu melakukannya dengan sempurna.','Guru memberi penguatan untuk langkah yang makin dekat dengan target.','Guru hanya memberi penguatan setelah siswa mencapai hasil sempurna.','Latihan bertahap menunjukkan bahwa siswa tidak sedang belajar.','Guru cukup memasangkan dua pemicu yang netral.'],
  'behavioristik.schedules':['Jadwal penguatan (reinforcement schedules)','Penguatan bisa diberikan berdasarkan jumlah respons atau waktu yang lewat. Patokannya bisa tetap atau berubah-ubah.','Rasio tetap (fixed ratio), karena jumlah responsnya tetap.','Interval tetap (fixed interval), karena angka lima tidak berubah.','Semua jadwal yang berubah-ubah menggunakan waktu tetap.','Jadwal rasio ditentukan oleh waktu sejak hadiah terakhir.'],
  'kognitif.schema':['Skema (schema)','Siswa memakai pola pengetahuan yang sudah dimiliki untuk memahami pengalaman. Pola itu dapat berkembang saat mendapat pengalaman baru.','Pengetahuan yang sudah dimiliki memengaruhi cara anak memahami pengalaman.','Skema adalah hadiah setelah anak melakukan perilaku tertentu.','Pengalaman baru tidak dapat mengubah skema anak.','Pemahaman anak hanya dipengaruhi pemicu dari luar.'],
  'kognitif.assimilation':['Asimilasi (assimilation)','Siswa memahami pengalaman baru dengan memakai kelompok atau pola pengetahuan yang sudah ada.','Anak memasukkan kelinci ke kelompok kucing yang sudah dikenalnya.','Anak sudah membuat kelompok baru khusus untuk kelinci.','Anak mengubah semua pola pengetahuan yang dimilikinya.','Kesalahan menyebut nama menunjukkan bahwa anak tidak belajar.'],
  'kognitif.accommodation':['Akomodasi (accommodation)','Siswa mengubah pola pengetahuan atau membuat kelompok baru agar pengalaman yang berbeda dapat dipahami.','Anak mengubah pengelompokannya agar sesuai dengan ciri kelinci.','Anak tetap memasukkan kelinci ke kelompok kucing.','Anak mendapat hadiah karena menyebut nama dengan benar.','Anak hanya dapat mengubah pengetahuan setelah dihukum.'],
  'kognitif.equilibration':['Ekuilibrasi (equilibration)','Saat pengalaman tidak cocok dengan pemahaman awal, siswa menyesuaikan pengetahuannya agar pengalaman itu masuk akal.','Hasil yang berbeda dari dugaan mendorong siswa memperbaiki pemahamannya.','Guru perlu menghindari setiap pengalaman yang bertentangan dengan dugaan siswa.','Dugaan yang salah menunjukkan perkembangan siswa berhenti selamanya.','Proses ini berarti siswa mampu mengingat semua fakta.'],
  'kognitif.sensorimotor':['Tahap sensorimotor (sensorimotor stage)','Pada tahap awal, bayi belajar lewat indra dan gerakan. Bayi mulai memahami bahwa benda tetap ada meski tidak terlihat.','Bayi mulai memahami benda tetap ada (object permanence).','Bayi sudah mampu menguji dugaan yang abstrak.','Mencari mainan menunjukkan seluruh kemampuan berpikir formal sudah terbentuk.','Bayi memahami bahwa benda hilang saat tidak terlihat.'],
  'kognitif.preoperational':['Tahap praoperasional (preoperational stage)','Anak mulai memakai kata dan gambar untuk mewakili sesuatu, tetapi sering menilai keadaan dari satu ciri saja.','Anak melihat tinggi air saja, sehingga mengira jumlahnya berubah.','Gelas yang lebih tinggi membuktikan jumlah air bertambah.','Anak sudah mempertimbangkan bahwa air dapat dituang kembali.','Kesalahan itu menunjukkan semua kemampuan anak rendah.'],
  'kognitif.concrete':['Tahap operasional konkret (concrete operational stage)','Anak lebih mampu berpikir logis tentang benda nyata, termasuk memahami jumlah tetap sama dan proses dapat dibalik.','Anak memahami jumlah air tetap sama karena bisa dituang kembali.','Jumlah tetap sama hanya jika bentuk wadah tidak berubah.','Anak menilai tinggi air saja tanpa mempertimbangkan proses menuang.','Anak pada tahap ini belum mampu berpikir logis.'],
  'kognitif.formal':['Tahap operasional formal (formal operational stage)','Siswa mulai mampu memikirkan hal abstrak dan menguji dugaan. Kemampuan yang tampak juga dipengaruhi tugas dan pengalaman.','Siswa menguji dugaan dengan mengubah satu variabel setiap kali.','Usia tertentu menjamin semua orang mampu berpikir abstrak pada setiap tugas.','Remaja tidak dapat mengerjakan tugas yang melibatkan gagasan abstrak.','Mengubah semua variabel sekaligus adalah cara mengontrol percobaan.'],
  'kognitif.representations':['Cara mewakili pengetahuan menurut Bruner','Pengetahuan dapat ditampilkan melalui tindakan (enactive), gambar (iconic), atau lambang seperti kata dan angka (symbolic). Ketiganya dapat digunakan bersama.','Tindakan, gambar, dan lambang membantu siswa memahami konsep yang sama.','Cara simbolik berarti siswa hanya boleh melihat gambar.','Ketiga cara itu membagi siswa ke dalam gaya belajar yang tetap.','Cara enaktif berarti menghafal angka tanpa melakukan tindakan.'],
  'kognitif.spiral':['Kurikulum spiral dan belajar melalui penemuan (spiral curriculum and discovery learning)','Siswa mempelajari kembali konsep dengan pembahasan yang makin dalam. Guru tetap memberi bantuan saat siswa mencari pemahaman.','Konsep diperdalam dan siswa tetap mendapat bimbingan.','Siswa mengulang contoh yang sama tanpa pembahasan lebih dalam.','Guru dilarang memberi bantuan saat siswa belajar melalui penemuan.','Setiap konsep hanya boleh diajarkan satu kali.'],
  'konstruktivistik.construction':['Membangun pengetahuan (knowledge construction)','Siswa menghubungkan pengalaman baru dengan pengetahuan sebelumnya. Guru tetap perlu memeriksa apa yang siswa pahami.','Guru perlu memeriksa pemahaman siswa setelah kegiatan.','Melakukan kegiatan fisik sudah menjamin siswa memahami konsep dengan benar.','Guru tidak boleh menjelaskan konsep kepada siswa.','Siswa menerima pengetahuan tanpa memberi makna pada pengalaman.'],
  'konstruktivistik.zpd':['Zona perkembangan proksimal (zone of proximal development, ZPD)','Ada tugas yang belum bisa dikerjakan siswa sendiri, tetapi bisa dikerjakan dengan bantuan yang sesuai.','Siswa dapat mengerjakan tugas itu dengan bantuan yang sesuai.','Tugas dalam ZPD sudah bisa dikerjakan siswa tanpa bantuan.','Setiap tugas sulit berada dalam ZPD siswa.','Berhasil dengan bantuan menunjukkan bantuan itu tidak diperlukan.'],
  'konstruktivistik.scaffolding':['Bantuan belajar bertahap (scaffolding)','Guru memberi bantuan sesuai kebutuhan siswa, lalu menguranginya saat siswa makin mampu belajar sendiri.','Guru mengurangi bantuan saat siswa makin mampu bekerja sendiri.','Guru memberi bantuan dengan jumlah yang sama selamanya.','Guru menghapus bantuan sebelum siswa mulai belajar.','Kerangka laporan membuat siswa tidak perlu memahami isi laporan.'],
  'konstruktivistik.mediation':['Peran bahasa dan budaya dalam berpikir','Menurut Vygotsky, bahasa, alat, dan kebiasaan budaya membantu siswa mengembangkan cara berpikir.','Bahasa dan interaksi membantu siswa membangun cara berpikir.','Cara berpikir siswa tidak berhubungan dengan budayanya.','Bahasa hanya dipakai setelah proses belajar selesai.','Semua budaya memberi siswa pengalaman belajar yang sama.'],
  'konstruktivistik.private-speech':['Bicara kepada diri sendiri (private speech)','Anak dapat memakai ucapan kepada dirinya sendiri untuk mengatur tindakan dan langkah berpikir.','Ucapan itu membantu anak mengatur langkah penyelesaian tugas.','Ucapan itu menunjukkan adanya gangguan perkembangan.','Anak berbicara kepada diri sendiri hanya untuk mendapat pujian.','Ucapan itu menunjukkan bahwa anak tidak mampu belajar.'],
  'konstruktivistik.collaboration':['Belajar bersama (collaborative learning)','Belajar bersama dapat membantu pemahaman jika setiap anggota menjelaskan gagasan dan menanggapi anggota lain.','Setiap anggota perlu ikut bertanggung jawab dan menjelaskan pemikirannya.','Duduk dalam satu kelompok sudah menjamin semua anggota paham.','Satu anggota sebaiknya mengerjakan seluruh tugas kelompok.','Perbedaan pendapat menghambat setiap proses belajar.'],
  'konstruktivistik.inquiry':['Inkuiri terbimbing (guided inquiry)','Siswa mencari jawaban lewat pertanyaan, data, dan penjelasan. Guru memberi petunjuk agar tugas dapat dikerjakan.','Siswa menyusun penjelasan dari bukti dengan bantuan guru.','Siswa cukup menebak jawaban tanpa mengumpulkan bukti.','Setiap petunjuk guru membuat kegiatan bukan lagi inkuiri.','Kesimpulan yang menarik boleh berbeda dari data yang dikumpulkan.'],
  'konstruktivistik.misconception':['Pengetahuan awal dan salah paham konsep (misconception)','Guru mencari tahu gagasan awal siswa, membandingkannya dengan bukti, lalu membantu memperbaiki pemahaman yang keliru.','Guru perlu membantu siswa menguji gagasan awalnya dengan bukti.','Hafal rumus menunjukkan semua salah paham konsep sudah hilang.','Menambah halaman bacaan akan menghilangkan salah paham konsep.','Pengetahuan awal tidak memengaruhi pemahaman materi baru.'],
  'memori.stores':['Model memori Atkinson–Shiffrin','Model ini membedakan memori sensorik, memori jangka pendek, dan memori jangka panjang, serta proses yang mengatur informasi.','Ketiga tempat penyimpanan informasi memiliki fungsi yang berbeda.','Semua informasi dari indra langsung tersimpan untuk selamanya.','Memori jangka pendek dapat menyimpan informasi tanpa batas.','Model ini menjelaskan belajar hanya sebagai hasil pemberian hadiah.'],
  'memori.attention':['Perhatian dan memori sensorik (attention and sensory memory)','Informasi dari indra bertahan sebentar. Perhatian membantu memilih informasi mana yang akan diproses lebih lanjut.','Animasi dan penjelasan bersaing mendapatkan perhatian siswa.','Melihat informasi menunjukkan siswa sudah memahaminya secara mendalam.','Memori sensorik dapat menyimpan semua informasi tanpa batas waktu.','Gangguan tambahan membuat siswa lebih fokus pada penjelasan utama.'],
  'memori.working-memory':['Memori kerja (working memory)','Sistem ini menyimpan informasi sebentar sambil mengolahnya untuk mengerjakan tugas. Kapasitasnya terbatas.','Mengingat instruksi sambil menghitung membebani memori kerja (working memory).','Memori kerja menyimpan semua informasi untuk selamanya tanpa batas.','Kesalahan itu sudah cukup membuktikan kecerdasan siswa rendah.','Menambah instruksi membuat beban memori siswa lebih ringan.'],
  'memori.components':['Komponen memori kerja (working memory components)','Menurut Baddeley, ada pengatur perhatian (central executive), pengolah bunyi atau kata (phonological loop), pengolah gambar dan ruang (visuospatial sketchpad), serta penggabung informasi (episodic buffer).','Mengingat kata dan mengingat bentuk peta memakai komponen yang berbeda.','Pengolah bunyi (phonological loop) terutama menyimpan bentuk peta.','Pengatur perhatian (central executive) hanya menyimpan suara.','Penggabung informasi (episodic buffer) hanya memberi hadiah atas perilaku.'],
  'memori.encoding':['Mengolah, menyimpan, dan mengingat kembali (encoding, storage, retrieval)','Informasi diolah agar bisa disimpan, dipertahankan dalam memori, lalu diingat kembali saat dibutuhkan.','Merasa mengenali bacaan belum berarti bisa mengingatnya tanpa petunjuk.','Merasa akrab dengan bacaan menunjukkan siswa bisa mengingatnya sendiri.','Mengingat kembali (retrieval) berarti pertama kali memasukkan informasi baru.','Berhasil menyimpan informasi berarti bisa mengingatnya setiap saat.'],
  'memori.elaboration':['Elaborasi dan pengelompokan informasi (elaboration and chunking)','Siswa menghubungkan informasi dengan makna yang sudah dikenal dan mengelompokkan bagian kecil menjadi kelompok yang bermakna.','Menghubungkan makna dan mengelompokkan istilah membantu siswa mengolah informasi.','Pengelompokan membuat kapasitas memori menjadi tidak terbatas.','Elaborasi berarti mengulang bunyi tanpa memahami maknanya.','Mengelompokkan istilah secara acak sama membantu dengan pengelompokan bermakna.'],
  'memori.retrieval-practice':['Latihan mengingat dan belajar berjeda (retrieval practice and spacing)','Siswa berlatih mengingat tanpa melihat catatan, memeriksa jawabannya, lalu mengulang pada waktu yang berbeda.','Mengingat sendiri, membahas kesalahan, dan memberi jeda membantu belajar.','Membaca ulang terus-menerus sama dengan berlatih mengingat sendiri.','Jawaban yang salah sebaiknya dibiarkan tanpa koreksi.','Jeda antarsesi menghilangkan semua manfaat latihan.'],
  'memori.load':['Beban kognitif (cognitive load)','Memori kerja punya kapasitas terbatas. Informasi yang tidak diperlukan dapat menyulitkan siswa memahami materi utama.','Mengurangi hiasan yang tidak relevan membantu siswa fokus pada materi.','Setiap media tambahan membuat siswa lebih paham.','Siswa pemula dan ahli membutuhkan bantuan yang sama.','Beban berpikir yang tinggi menunjukkan siswa belajar lebih banyak.'],
  'humanistik.maslow':['Kebutuhan menurut Maslow (hierarchy of needs)','Kebutuhan fisik, rasa aman, hubungan, penghargaan, dan pengembangan diri dapat memengaruhi belajar. Urutannya tidak selalu kaku.','Guru perlu mempertimbangkan rasa lapar dan rasa aman siswa.','Siswa baru dapat belajar setelah semua kebutuhannya terpenuhi sempurna.','Kebutuhan fisik tidak berpengaruh pada proses belajar.','Hierarki kebutuhan dapat langsung menentukan diagnosis siswa.'],
  'humanistik.rogers':['Belajar berpusat pada siswa (student-centered learning)','Guru membantu siswa belajar melalui pengalaman yang bermakna dan menghargai kebutuhan serta pilihan siswa.','Pilihan proyek yang bermakna dan bantuan guru mendukung keterlibatan siswa.','Belajar berpusat pada siswa berarti tidak perlu tujuan belajar.','Guru harus menghapus semua aturan dan arahan.','Siswa hanya bisa belajar secara bermakna jika mendapat hadiah.'],
  'humanistik.empathy':['Empati dan penerimaan (empathy and acceptance)','Guru berusaha memahami pengalaman siswa dan menghargai dirinya, sambil tetap membahas hal yang perlu diperbaiki.','Guru dapat menghargai siswa sambil mengoreksi pekerjaannya.','Menghargai siswa berarti menyetujui setiap jawabannya.','Berempati berarti menghapus semua standar belajar.','Umpan balik hanya membantu jika guru mempermalukan siswa.'],
  'humanistik.kolb-experience':['Pengalaman konkret dan refleksi (concrete experience and reflective observation)','Dalam siklus Kolb, siswa meninjau pengalaman yang sudah terjadi sebelum menyusun penjelasan dan mencoba tindakan berikutnya.','Mahasiswa meninjau pengalaman mengajar yang baru dilakukannya.','Melakukan kegiatan sudah menjamin semua konsep dipahami dengan benar.','Refleksi berarti langsung mencoba lagi tanpa meninjau pengalaman.','Siklus Kolb hanya melibatkan hafalan teori.'],
  'humanistik.kolb-concept':['Menyusun konsep dan mencoba tindakan (abstract conceptualization and active experimentation)','Siswa menyusun penjelasan dari pengalaman, lalu menguji penjelasan itu melalui tindakan berikutnya.','Mahasiswa memakai penjelasannya untuk mencoba strategi baru.','Menyusun penjelasan sama dengan sekadar mengalami kejadian.','Mencoba tindakan baru membuat refleksi tidak diperlukan.','Penjelasan tidak perlu diuji pada kegiatan berikutnya.'],
  'humanistik.humanistic-practice':['Penerapan pendekatan humanistik','Guru membangun suasana aman, memberi pilihan yang sesuai, dan menetapkan tujuan bermakna. Hasil belajar tetap dinilai.','Guru memberi siswa pilihan dengan kriteria penilaian yang jelas.','Pendekatan humanistik menolak setiap bentuk penilaian.','Pilihan siswa tidak boleh disertai kriteria penilaian.','Suasana nyaman menunjukkan semua siswa sudah menguasai konsep.'],
  'ekologis.micro':['Mikrosistem (microsystem)','Siswa berinteraksi langsung dengan lingkungan ini, seperti keluarga, kelas, dan teman sebaya.','Interaksi siswa dengan wali kelas termasuk mikrosistem (microsystem).','Setiap hubungan langsung siswa termasuk eksosistem (exosystem).','Mikrosistem hanya mencakup kebijakan tingkat nasional.','Hubungan langsung tidak memengaruhi pengalaman belajar siswa.'],
  'ekologis.meso':['Mesosistem (mesosystem)','Lingkungan yang berhubungan langsung dengan siswa juga saling terhubung, misalnya keluarga bekerja sama dengan sekolah.','Kerja sama orang tua dan guru termasuk mesosistem (mesosystem).','Mesosistem hanya berarti satu interaksi langsung dengan siswa.','Kerja sama rumah dan sekolah hanya termasuk makrosistem (macrosystem).','Hubungan antara rumah dan sekolah tidak dibahas dalam teori ekologis.'],
  'ekologis.exo':['Eksosistem (exosystem)','Siswa tidak ikut berada dalam lingkungan ini, tetapi perubahan di sana tetap dapat memengaruhi hidupnya.','Jadwal kerja orang tua memengaruhi belajar siswa secara tidak langsung.','Tempat kerja hanya berpengaruh jika siswa hadir di sana.','Setiap pengaruh tidak langsung termasuk mikrosistem (microsystem).','Eksosistem hanya menjelaskan bertambahnya usia siswa.'],
  'ekologis.macro':['Makrosistem (macrosystem)','Nilai budaya dan keadaan masyarakat yang lebih luas membentuk lingkungan tempat siswa tumbuh.','Pandangan masyarakat tentang pendidikan termasuk pengaruh makrosistem.','Budaya hanya memengaruhi percakapan langsung antara dua siswa.','Makrosistem berarti memberi siswa bantuan pada setiap langkah tugas.','Nilai masyarakat tidak berhubungan dengan cara sekolah mengajar.'],
  'ekologis.chrono':['Kronosistem (chronosystem)','Perubahan hidup dan lingkungan dari waktu ke waktu ikut memengaruhi perkembangan siswa.','Perubahan keluarga dan cara belajar dari waktu ke waktu perlu diperhatikan.','Kronosistem hanya membahas lokasi ruang kelas.','Setiap perubahan berdampak sama pada semua siswa.','Waktu tidak memengaruhi lingkungan perkembangan siswa.'],
  'ekologis.contextual':['Pembelajaran kontekstual (contextual teaching and learning, CTL)','Siswa menghubungkan konsep dengan masalah nyata yang bermakna, lalu mencoba memakai pemahamannya pada situasi lain.','Siswa memakai konteks nyata, lalu mencoba konsep pada situasi berbeda.','Menambahkan cerita apa pun sudah membuat pembelajaran menjadi kontekstual.','Pembelajaran kontekstual berarti bermain tanpa mempelajari konsep.','Pemahaman siswa cukup diperiksa lewat satu contoh yang sama.'],
  'inteligensi.spearman':['Spearman: kemampuan umum dan khusus (g and s factors)','Faktor g menunjukkan kemampuan umum yang berkaitan dengan berbagai tugas. Faktor s menunjukkan kemampuan khusus untuk tugas tertentu.','Kemampuan umum dan kemampuan khusus dapat menjelaskan pola hasil tes.','Faktor g berarti semua kemampuan siswa sama persis.','Faktor s berarti satu kemampuan umum untuk seluruh tugas.','Hubungan antarhasil tes membuktikan lingkungan tidak berpengaruh.'],
  'inteligensi.gardner':['Gardner: kecerdasan majemuk (multiple intelligences)','Gardner membahas delapan ranah kemampuan, seperti bahasa, musik, gerak, dan hubungan sosial. Bukti bahwa ranah itu berdiri sendiri masih diperdebatkan.','Kegiatan yang beragam belum membuktikan tiap ranah kecerdasan berdiri sendiri.','Memakai musik dan peta sudah membuktikan seluruh teori Gardner.','Kecerdasan majemuk sama dengan preferensi visual, auditori, dan kinestetik (VAK).','Kemampuan musik yang baik menunjukkan IQ keseluruhan rendah.'],
  'inteligensi.sternberg':['Sternberg: teori triarkis (triarchic theory of intelligence)','Teori ini membahas kemampuan menganalisis, membuat solusi baru, dan memakai solusi sesuai keadaan nyata.','Tugas itu memakai kemampuan analitis, kreatif, dan praktis.','Tiga kemampuan itu adalah visual, auditori, dan kinestetik.','Kemampuan praktis hanya berarti menghafal definisi.','Kemampuan kreatif tidak berkaitan dengan menyelesaikan masalah.'],
  'inteligensi.fluid':['Inteligensi fluid dan terkristalisasi (fluid and crystallized intelligence)','Kemampuan fluid membantu menghadapi masalah baru. Kemampuan terkristalisasi memakai pengetahuan yang diperoleh lewat pengalaman dan belajar.','Memecahkan pola baru berbeda dari memakai kosakata yang sudah dipelajari.','Kemampuan fluid hanya dipakai untuk mengingat kosakata lama.','Kemampuan terkristalisasi tidak memakai pengalaman belajar.','Kedua kemampuan itu sama dengan jenis gaya belajar berdasarkan indra.'],
  'inteligensi.iq':['IQ modern (intelligence quotient)','Skor tes dibandingkan dengan kelompok pembanding yang sesuai. IQ tidak merangkum semua kemampuan atau nilai diri seseorang.','Skor perlu dibandingkan dengan norma dan dilihat sesuai cakupan tes.','IQ modern selalu dihitung dari usia mental dibagi usia sebenarnya.','IQ menentukan nilai moral dan memastikan masa depan seseorang.','Satu skor IQ dapat menunjukkan semua kemampuan seseorang.'],
  'inteligensi.reliability':['Reliabilitas (reliability)','Pengukuran menghasilkan nilai yang cukup konsisten dalam kondisi yang sesuai. Konsisten belum tentu berarti mengukur kemampuan yang dituju.','Hasil yang konsisten belum membuktikan tes mengukur kemampuan yang tepat.','Hasil yang stabil menjamin tes mengukur kemampuan yang dituju.','Reliabilitas hanya berarti soal terlihat masuk akal.','Tes yang konsisten tidak mungkin mengandung bias.'],
  'inteligensi.validity':['Validitas (validity)','Bukti perlu mendukung cara menafsirkan skor dan tujuan penggunaan tes. Skor tidak bisa dipakai untuk semua tujuan.','Bahasa tes dapat menghambat penilaian kemampuan penalaran siswa.','Skor setiap tes boleh digunakan untuk tujuan apa pun.','Tes memiliki validitas yang sama pada setiap konteks penggunaan.','Bahasa yang belum dikuasai tidak dapat memengaruhi hasil tes.'],
  'inteligensi.vak':['Preferensi visual, auditori, dan kinestetik (VAK)','Siswa dapat menyukai gambar, suara, atau gerakan. Kesukaan itu belum membuktikan bahwa mencocokkan cara mengajar dengan label VAK meningkatkan hasil belajar.','Kesukaan pada diagram tidak berarti siswa harus dibatasi pada gambar.','Siswa yang suka gambar tidak bisa belajar lewat penjelasan lisan.','Label VAK tetap sepanjang hidup dan menentukan kemampuan siswa.','Mencocokkan metode dengan VAK sudah terbukti membantu semua siswa.'],
  'inteligensi.adaptation':['Pengajaran adaptif (adaptive teaching)','Guru menyesuaikan bantuan dengan pengetahuan awal, kebutuhan, dan hambatan siswa, sambil tetap menjaga tujuan belajar.','Guru dapat memberi bantuan berbeda tanpa otomatis menurunkan tujuan belajar.','Perbedaan siswa berarti semua tujuan belajar harus diturunkan.','Setiap siswa hanya boleh belajar lewat satu jenis media.','Cara mengajar untuk ahli juga paling cocok untuk pemula.'],
  'inteligensi.fairness':['Keadilan dalam penilaian (fairness in assessment)','Guru mempertimbangkan bahasa, akses, dan keadaan saat tes berlangsung. Hasil tes perlu dilihat bersama informasi lain.','Guru perlu melihat perbedaan akses dan kondisi saat membandingkan skor.','Prosedur yang sama menjamin kesempatan siswa sudah setara.','Satu tes cukup untuk membuat semua keputusan pendidikan.','Kondisi saat tes tidak memengaruhi penafsiran skor.'],
  'domain.domains':['Ranah kognitif, afektif, dan psikomotorik (cognitive, affective, psychomotor domains)','Tujuan belajar dapat menyangkut pengetahuan, sikap atau nilai, dan kemampuan melakukan keterampilan.','Tugas melibatkan pengetahuan, sikap, dan keterampilan melakukan tindakan.','Semua tujuan dalam tugas itu hanya mengukur hafalan.','Sikap dan nilai hanya berarti kemampuan menggerakkan alat.','Keterampilan gerak cukup dinilai lewat definisi tertulis.'],
  'domain.affective-levels':['Tahapan afektif Krathwohl (affective taxonomy)','Siswa mulai memperhatikan (receiving), menanggapi (responding), menghargai (valuing), menyusun nilai (organization), lalu menjalankannya secara konsisten (characterization).','Siswa makin menghayati nilai, dari memperhatikan hingga menjalankannya konsisten.','Mendengar aturan sekali menunjukkan nilai sudah dijalankan secara konsisten.','Tahapan afektif menjelaskan urutan gerakan otot.','Ikut kegiatan menunjukkan nilai sudah menjadi kebiasaan yang stabil.'],
  'domain.attitudes':['Sikap, minat, dan nilai (attitudes, interests, values)','Pandangan siswa, ketertarikannya, dan hal yang dianggap penting dapat memengaruhi belajar. Keadaan kelas juga perlu diperhatikan.','Siswa bisa berminat tetapi tetap enggan menjawab karena merasa tidak aman.','Tidak menjawab menunjukkan siswa tidak berminat pada topik itu.','Satu tindakan sudah menunjukkan seluruh nilai pribadi siswa.','Sikap dan minat tidak dipengaruhi keadaan kelas.'],
  'domain.bloom-revised':['Taksonomi Bloom revisi (revised Bloom taxonomy)','Proses berpikir mencakup mengingat (remember), memahami (understand), menerapkan (apply), menganalisis (analyze), menilai (evaluate), dan mencipta (create).','Siswa harus menilai pilihan dengan bukti, bukan hanya mengingat istilah.','Setiap soal pilihan ganda hanya mengukur hafalan.','Soal yang panjang sudah termasuk mencipta (create).','Hafal nama tokoh sudah menunjukkan kemampuan menilai (evaluate).'],
  'domain.simpson-early':['Simpson: persepsi, kesiapan, respons terbimbing (perception, set, guided response)','Siswa mengenali petunjuk gerakan, menyiapkan diri, lalu meniru atau mencoba dengan bimbingan.','Mahasiswa masih melakukan keterampilan dengan bimbingan tutor.','Mencoba sekali dengan tutor menunjukkan gerakan sudah otomatis.','Kesiapan (set) berarti menciptakan teknik gerakan baru.','Persepsi (perception) berarti menyusun argumen abstrak.'],
  'domain.simpson-skilled':['Simpson: gerakan terbiasa dan terampil (mechanism and complex overt response)','Dengan latihan, gerakan menjadi lebih terbiasa dan dapat dilakukan dengan tepat serta lancar.','Latihan membantu siswa melakukan rangkaian gerakan dengan lebih lancar.','Kelancaran gerak cukup dinilai lewat tes definisi.','Latihan terarah tidak mengubah keterampilan siswa.','Gerakan yang lancar berarti siswa menciptakan teknik baru setiap kali.'],
  'domain.simpson-adapt':['Simpson: penyesuaian dan penciptaan gerak (adaptation and origination)','Siswa dapat menyesuaikan keterampilan dengan situasi baru atau membuat pola gerakan untuk kebutuhan tertentu.','Praktikan menyesuaikan teknik yang dikuasai dengan ukuran alat baru.','Praktikan hanya sedang mengenali petunjuk dari indra.','Penyesuaian (adaptation) berarti meniru tanpa mengubah teknik.','Setiap gerakan baru dilakukan tanpa tujuan.'],
  'domain.performance':['Penilaian keterampilan (performance assessment)','Guru mengamati siswa melakukan keterampilan dengan kriteria yang sesuai. Hafal langkah belum berarti mampu mempraktikkannya.','Guru perlu mengamati siswa menggunakan alat secara langsung.','Hafal langkah menunjukkan siswa sudah bisa menggunakan alat.','Kriteria penilaian tidak perlu sesuai dengan keterampilan yang dituju.','Kecepatan gerak saja cukup untuk mengetahui sikap siswa.'],
  'motivasi.intrinsic':['Motivasi intrinsik (intrinsic motivation)','Siswa melakukan kegiatan karena kegiatan itu sendiri menarik atau memuaskan baginya.','Siswa belajar karena tertarik memahami pertanyaan itu.','Siswa belajar tambahan hanya untuk mendapat hadiah dari luar.','Motivasi intrinsik berarti siswa tidak perlu berusaha.','Motivasi intrinsik hanya ada saat siswa tidak punya tujuan.'],
  'motivasi.extrinsic':['Motivasi ekstrinsik (extrinsic motivation)','Siswa melakukan kegiatan untuk memperoleh hasil di luar kegiatan itu, misalnya nilai, beasiswa, atau pengakuan.','Siswa belajar untuk mendapatkan beasiswa melalui nilai yang baik.','Motivasi ekstrinsik membuat siswa tidak pernah memahami materi.','Semua bentuk motivasi ekstrinsik berdampak sama.','Beasiswa adalah kepuasan yang berasal dari kegiatan belajar itu sendiri.'],
  'motivasi.sdt':['Otonomi, kompetensi, keterhubungan (autonomy, competence, relatedness)','Teori determinasi diri (self-determination theory, SDT) membahas kebutuhan untuk punya pilihan, merasa mampu, dan merasa terhubung. Guru tetap dapat memberi arahan.','Guru mendukung pilihan, kemampuan, dan hubungan siswa dengan arahan yang jelas.','Memberi pilihan berarti guru harus menghapus semua arahan.','Membantu siswa merasa mampu berarti semua tugas harus sangat mudah.','Membangun hubungan hanya berarti memberi hadiah untuk nilai tinggi.'],
  'motivasi.efficacy':['Keyakinan mampu mengerjakan tugas (self-efficacy)','Keyakinan siswa bahwa ia mampu melakukan tugas tertentu dapat memengaruhi usaha dan ketekunannya.','Keberhasilan bertahap membantu siswa yakin mampu mengerjakan tugas itu.','Keyakinan pada tugas sama dengan penilaian seluruh nilai diri seseorang.','Percaya diri menjamin hasil tugas akan sempurna.','Keyakinan siswa tidak berhubungan dengan pengalaman sebelumnya.'],
  'motivasi.goals':['Tujuan penguasaan dan pembuktian kemampuan (mastery and performance goals)','Siswa dapat berfokus memperbaiki pemahaman atau menunjukkan kemampuan dibandingkan orang lain.','Siswa lebih berfokus memperbaiki pemahaman daripada mengalahkan teman.','Tujuan penguasaan hanya berarti mendapat nilai lebih tinggi dari teman.','Tujuan pembuktian kemampuan berarti siswa tidak belajar sama sekali.','Tujuan siswa tidak memengaruhi cara menghadapi kesalahan.'],
  'motivasi.attribution':['Penjelasan hasil belajar (attribution)','Cara siswa menjelaskan keberhasilan atau kegagalan, misalnya melalui usaha dan strategi, dapat memengaruhi langkah berikutnya.','Siswa melihat strategi yang bisa diubah untuk memperbaiki hasil belajar.','Gagal sekali menunjukkan kemampuan siswa akan tetap rendah.','Semua hasil belajar hanya ditentukan oleh usaha siswa sendiri.','Penjelasan siswa tentang hasil tidak memengaruhi cara belajar berikutnya.'],
  'motivasi.srl-plan':['Pengaturan diri dalam belajar: perencanaan (self-regulated learning, planning)','Sebelum belajar, siswa menetapkan target, memilih cara belajar, dan menyiapkan hal yang dibutuhkan.','Siswa memilih latihan yang sesuai dengan target belajarnya.','Merencanakan belajar berarti tidak perlu tujuan atau strategi.','Menentukan jam belajar menunjukkan materi sudah dikuasai.','Cara belajar tidak perlu sesuai dengan jenis materi.'],
  'motivasi.srl-monitor':['Pengaturan diri dalam belajar: pemantauan (self-regulated learning, monitoring)','Saat belajar, siswa memeriksa apa yang sudah dipahami dan mengganti cara belajar bila diperlukan.','Siswa memeriksa pemahaman dengan mencoba menjelaskan tanpa catatan.','Merasa mengenali bacaan sudah membuktikan siswa menguasai materi.','Siswa baru boleh memeriksa pemahaman setelah semester berakhir.','Cara belajar harus tetap sama meskipun tidak membantu.'],
  'motivasi.srl-evaluate':['Pengaturan diri dalam belajar: evaluasi dan refleksi (self-regulated learning, evaluation)','Setelah belajar, siswa membandingkan hasil dengan target dan mencari hal yang perlu diperbaiki pada sesi berikutnya.','Siswa memakai pola kesalahan untuk merencanakan latihan berikutnya.','Siswa cukup mencatat skor tanpa melihat kembali kesalahan.','Skor rendah berarti semua cara belajar harus diulang tanpa perubahan.','Refleksi tidak perlu melihat target belajar yang sudah ditetapkan.'],
  'motivasi.engagement':['Keterlibatan belajar (student engagement)','Keterlibatan mencakup tindakan, perasaan, dan usaha memahami materi. Datang ke kelas saja belum cukup.','Siswa dapat aktif berpikir meskipun tidak banyak berbicara.','Siswa yang diam berarti tidak terlibat dalam belajar.','Hadir di kelas menunjukkan keterlibatan siswa sudah tinggi dalam semua hal.','Keterlibatan belajar hanya terlihat dari nilai tes akhir.'],
  'kesulitan.difficulty':['Kesulitan belajar (learning difficulties)','Kesulitan dapat muncul karena berbagai sebab. Nilai rendah saja belum cukup untuk menentukan gangguan belajar tertentu.','Guru perlu melihat pengajaran yang pernah diterima siswa.','Setiap nilai rendah menunjukkan gangguan belajar tertentu.','Kesulitan belajar hanya disebabkan oleh IQ rendah.','Satu kuis cukup untuk menentukan diagnosis siswa.'],
  'kesulitan.reading':['Kesulitan membaca (reading difficulties)','Guru perlu menilai kemampuan menghubungkan huruf dengan bunyi (decoding) dan kelancaran membaca, serta melihat riwayat belajar siswa.','Siswa perlu penilaian kemampuan membaca dan bantuan yang sesuai.','Kesulitan itu menunjukkan siswa malas membaca.','Salah membalik satu huruf sudah membuktikan disleksia (dyslexia).','Kesulitan membaca membuat semua kemampuan lain hilang.'],
  'kesulitan.math':['Kesulitan matematika (mathematics difficulties)','Guru memeriksa konsep bilangan dan operasi yang belum dipahami, lalu memberi bantuan pada bagian itu.','Guru perlu membantu siswa memahami nilai tempat lebih dahulu.','Memberi lebih banyak soal sulit akan menyelesaikan masalah dasarnya.','Setiap kesalahan menghitung membuktikan diskalkulia (dyscalculia).','Pengajaran sebelumnya tidak memengaruhi kemampuan matematika.'],
  'kesulitan.writing':['Kesulitan menulis (writing difficulties)','Hambatan dapat muncul pada gerakan menulis, penggunaan bahasa, atau penyusunan gagasan. Bantuan perlu sesuai dengan hambatannya.','Guru perlu membedakan kemampuan menjelaskan lisan dan menyusun tulisan.','Mampu menjelaskan lisan menunjukkan semua keterampilan menulis sudah baik.','Setiap kesulitan menulis hanya disebabkan gerakan tangan.','Semua kesulitan menulis cukup ditangani dengan latihan yang sama.'],
  'kesulitan.emotion':['Emosi dan kecemasan belajar (learning anxiety)','Perasaan dapat memengaruhi perhatian dan hasil tugas. Rasa aman dan bantuan yang sesuai dapat mendukung siswa.','Kecemasan dapat menghambat jawaban meskipun siswa memahami materi.','Nilai ujian menunjukkan kemampuan yang sama pada setiap keadaan.','Siswa yang cemas berarti belum pernah mempelajari materi.','Mempermalukan siswa membantu menghilangkan kecemasan.'],
  'kesulitan.environment':['Lingkungan dan keluarga','Perangkat, bahan belajar, dukungan keluarga, dan suasana tempat belajar dapat menjadi hambatan di luar kemampuan berpikir siswa.','Guru perlu mempertimbangkan akses perangkat dan suasana belajar.','Kesulitan itu menunjukkan kecerdasan siswa rendah.','Semua keluarga memiliki fasilitas belajar yang sama.','Kondisi lingkungan tidak perlu diperhatikan guru.'],
  'kesulitan.identification':['Mengenali kebutuhan belajar','Guru menggabungkan pengamatan, hasil tugas, riwayat belajar, dan informasi pihak terkait. Dugaan perlu dibedakan dari data.','Berbagai informasi membantu guru memahami kebutuhan siswa dengan lebih tepat.','Satu tindakan siswa cukup untuk mengetahui semua penyebab kesulitannya.','Riwayat belajar dan perubahan setelah bantuan tidak perlu diperiksa.','Pengamatan guru sudah menggantikan penilaian oleh tenaga profesional.'],
  'kesulitan.intervention':['Bantuan dan pemantauan kemajuan (intervention and progress monitoring)','Guru menetapkan target bantuan, memeriksa kemajuan, lalu menyesuaikan bantuan bila perlu. Rujukan dapat dilakukan sesuai kebutuhan.','Bantuan perlu punya target dan kemajuannya perlu dipantau.','Bantuan yang tidak berhasil harus diteruskan tanpa perubahan.','Semua siswa perlu didiagnosis sebelum mendapat bantuan belajar.','Hasil satu hari sudah memastikan apakah bantuan berhasil.'],
  'desain.analysis':['ADDIE: analisis (analysis)','Tim memahami kebutuhan siswa, kemampuan awal, dan hambatan sebelum menentukan rancangan pembelajaran.','Tim perlu mencari tahu kebutuhan dan akses siswa lebih dahulu.','Tim harus memilih aplikasi sebelum memahami kebutuhan siswa.','Analisis hanya berarti membuat seluruh tampilan aplikasi.','Akses perangkat tidak termasuk hal yang perlu diperiksa.'],
  'desain.design':['ADDIE: perancangan (design)','Tim merancang tujuan, kegiatan, cara mengajar, dan penilaian agar saling sesuai sebelum membuat bahan.','Tujuan, latihan, dan penilaian perlu menguji kemampuan yang sama.','Perancangan hanya berarti memilih warna halaman.','Penilaian tidak perlu sesuai dengan tujuan belajar.','Kehadiran saja cukup untuk menilai semua tujuan belajar.'],
  'desain.development':['ADDIE: pengembangan (development)','Tim membuat bahan sesuai rancangan, mengujinya, lalu memperbaiki bagian yang belum sesuai.','Tim membuat modul dan memperbaikinya berdasarkan hasil uji.','Pengembangan hanya berarti menentukan masalah awal.','Bahan yang sudah ditulis tidak perlu diuji.','Tim baru boleh memperbaiki bahan setelah satu semester.'],
  'desain.implementation':['ADDIE: pelaksanaan (implementation)','Tim menjalankan kegiatan belajar serta menyiapkan guru, siswa, dan sarana yang dibutuhkan.','Guru, siswa, dan sarana perlu siap sebelum kegiatan dijalankan.','Pelaksanaan hanya berarti menyusun daftar kebutuhan.','Mengunggah bahan sudah menjamin bahan digunakan dengan baik.','Bantuan teknis tidak memengaruhi pelaksanaan kegiatan.'],
  'desain.evaluation':['ADDIE: evaluasi (evaluation)','Tim memeriksa kualitas proses dan hasil. Pemeriksaan dapat dilakukan sejak pengembangan, bukan hanya setelah kegiatan selesai.','Tim memakai hasil uji awal untuk memperbaiki produk sebelum digunakan luas.','Evaluasi baru boleh dilakukan setelah seluruh produk selesai.','Jumlah klik menunjukkan siswa sudah memahami konsep.','Hasil evaluasi tidak boleh mengubah rancangan sebelumnya.'],
  'desain.alignment':['Keselarasan tujuan, kegiatan, dan penilaian (constructive alignment)','Tujuan belajar, kegiatan siswa, dan penilaian perlu mengarah pada kemampuan yang sama.','Ujian hafalan belum sesuai dengan tujuan membuat rekomendasi.','Hafal istilah menunjukkan siswa sudah mampu membuat rekomendasi.','Kegiatan yang menarik sudah menjamin tujuan dan penilaian sesuai.','Tujuan belajar tidak perlu dipertimbangkan saat memilih penilaian.'],
  'desain.technology':['Memilih media dan teknologi belajar','Tim memilih media yang membantu tujuan belajar, sesuai kebutuhan siswa, dan dapat diakses. Media terbaru belum tentu lebih membantu.','Tim perlu memilih media yang sesuai dengan kesulitan dan tujuan belajar.','Teknologi terbaru menghasilkan pembelajaran terbaik.','Harga aplikasi saja menentukan manfaatnya untuk belajar.','Setiap tujuan belajar membutuhkan media yang paling rumit.'],
  'desain.feedback':['Umpan balik untuk perbaikan (actionable feedback)','Guru menjelaskan bagian yang belum dipahami dan langkah perbaikannya, lalu memberi kesempatan siswa mencoba lagi.','Siswa perlu pembahasan kesalahan dan arahan latihan selain skor.','Skor saja sudah cukup memperbaiki semua salah paham konsep.','Umpan balik sebaiknya menilai pribadi siswa.','Siswa tidak perlu mencoba menerapkan saran perbaikan.'],
  'observasi.operational':['Menentukan perilaku yang diamati (operational definition)','Pengamat menetapkan perilaku (behavior) yang dicatat, waktu pengamatan, dan kriteria pencatatannya.','Pengamat perlu menyepakati tanda keaktifan yang akan dicatat.','Pengamat cukup menilai keaktifan berdasarkan kesan pribadi.','Semua pengamat memahami istilah keaktifan dengan cara yang sama.','Tanda keaktifan baru boleh ditetapkan setelah hasil pengamatan selesai.'],
  'observasi.inference':['Data pengamatan dan penafsiran (observation and interpretation)','Apa yang terlihat berbeda dari dugaan tentang penyebabnya. Pengamat perlu menandai dugaan dan mencari bukti tambahan.','Tidak menjawab belum cukup untuk memastikan penyebabnya.','Tidak menjawab menunjukkan siswa tidak punya motivasi.','Kejadian yang terlihat sama dengan penjelasan tentang penyebabnya.','Dugaan pengamat tidak perlu diperiksa lagi.'],
  'observasi.triangulation':['Memeriksa beberapa sumber informasi (triangulation)','Pengamat membandingkan informasi dari beberapa sumber atau cara pengumpulan data, termasuk bagian yang tidak sesuai.','Beberapa sumber membantu pengamat memeriksa penjelasan rendahnya partisipasi.','Beberapa sumber menjamin hasil pengamatan bebas dari semua bias.','Perbedaan informasi antarsumber harus diabaikan.','Tiga pendapat yang sama sudah membuktikan hubungan sebab akibat.'],
  'observasi.interview':['Pertanyaan wawancara yang netral (non-leading questions)','Pengamat menanyakan pengalaman dengan pertanyaan terbuka, tanpa mengarahkan orang pada jawaban yang sudah diinginkan.','Pertanyaan netral mengurangi dorongan untuk memberi jawaban tertentu.','Pertanyaan yang mengarahkan jawaban menghasilkan informasi lebih akurat.','Wawancara berguna hanya jika jawabannya sudah ditentukan.','Memakai pertanyaan terbuka berarti tidak perlu tujuan wawancara.'],
  'observasi.ethics':['Etika observasi pendidikan','Pengamat mengikuti prosedur izin dan menjaga privasi serta kerahasiaan informasi peserta.','Nama dan informasi pribadi siswa perlu dilindungi.','Izin berkunjung memberi hak untuk menyebarkan seluruh data siswa.','Tujuan pendidikan membuat privasi siswa tidak diperlukan.','Menyamarkan identitas membuat perilaku siswa tidak bisa dianalisis.'],
  'observasi.current-issues':['Isu pendidikan dan bukti terbaru','Sebelum memakai hasil penelitian, pengamat memeriksa tanggal, cara penelitian, dan kesesuaiannya dengan keadaan sekolah.','Tim perlu melihat apakah keadaan sekolah sesuai dengan konteks penelitian.','Artikel terbaru berlaku untuk semua sekolah.','Tanggal terbit saja menentukan kualitas penelitian.','Perbedaan akses internet tidak memengaruhi penerapan temuan.'],
  'sintesis.multi-theory':['Menggabungkan beberapa teori (theoretical synthesis)','Tim memakai teori yang membantu menjelaskan bagian-bagian kasus dan hubungan di antaranya, bukan hanya menyebut banyak nama tokoh.','Tim dapat menelaah beban berpikir, rasa takut, dan dukungan rumah bersama.','Satu teori dapat menjelaskan semua bagian dari setiap kasus.','Menyebut banyak teori sudah menghasilkan analisis yang kuat.','Teori yang dipilih tidak perlu berhubungan dengan data kasus.'],
  'sintesis.mechanism':['Menjelaskan bagaimana masalah terjadi (mechanism)','Tim menjelaskan bagaimana suatu faktor dapat memengaruhi proses belajar, lalu menunjukkan bukti yang mendukung penjelasannya.','Tim perlu menjelaskan bagaimana faktor itu memengaruhi proses belajar.','Menyebut faktor psikologis saja sudah menjelaskan penyebab masalah.','Menyalin nama teori sudah menjelaskan proses terjadinya masalah.','Semua faktor memengaruhi belajar lewat proses yang sama.'],
  'sintesis.recommendation':['Rekomendasi berdasarkan temuan','Tim memilih tindakan yang sesuai dengan kebutuhan dalam data, dapat dilakukan, dan bisa dinilai hasilnya.','Latihan itu menyasar perbedaan konsep yang belum dipahami siswa.','Rekomendasi harus sama meskipun data kasus berbeda.','Aplikasi baru menyelesaikan setiap masalah belajar.','Tindakan tidak perlu sesuai dengan tujuan perbaikan.'],
  'sintesis.causality':['Korelasi dan sebab akibat (correlation and causation)','Dua hal yang saling berkaitan belum tentu saling menyebabkan. Tim perlu memeriksa penjelasan lain dan cara penelitian dilakukan.','Pengetahuan awal yang lebih kuat bisa ikut menjelaskan perbedaan nilai.','Hubungan aplikasi dan nilai membuktikan aplikasi adalah satu-satunya penyebab.','Setiap penelitian pengamatan dapat memastikan sebab tanpa syarat lain.','Kemampuan awal tidak perlu diperiksa saat membandingkan kelompok.'],
  'sintesis.outcome':['Menilai hasil rekomendasi (outcome evaluation)','Tim menentukan hasil yang ingin berubah, kondisi awal, dan waktu pemeriksaan agar perubahan dapat dinilai.','Tim perlu melihat hasil belajar siswa selain jumlah guru yang memakai strategi.','Jumlah pemakaian menunjukkan pemahaman siswa meningkat.','Penilaian hasil tidak membutuhkan informasi kondisi awal.','Semua perubahan setelah bantuan disebabkan oleh bantuan itu.'],
  'sintesis.presentation':['Menyampaikan hasil analisis','Tim menjelaskan masalah, data, alasan, rekomendasi, dan batas kesimpulan agar orang lain dapat memeriksa argumennya.','Tim perlu menunjukkan hubungan data, penjelasan, dan rekomendasi.','Presentasi yang menarik sudah dapat menggantikan bukti.','Tim perlu menyembunyikan keterbatasan agar argumennya kuat.','Rekomendasi tidak perlu berkaitan dengan masalah yang diamati.'],
};

