export function quizConcept(concept){
  const row=quizWording[concept.id];
  if(!row)return concept;
  return {...concept,title:row[0],text:row[1],conclusion:row[2],distractors:row.slice(3),scenario:quizScenarios[concept.id]||concept.scenario};
}
